+                .first,
+          );
+          expect(audioInkWell.onTap, isNull);
+
+          final closeInkWell = tester.widget<InkWell>(
+            find
+                .ancestor(
+                  of: find.byIcon(Icons.close),
+                  matching: find.byType(InkWell),
